/**
 * load-pse-financials.ts
 *
 * Loads real, source-scraped PSE fundamentals from
 * data/pse-financial-history.json (generated by
 * scripts/scrape-pse-financial-history.ts from PSE EDGE quarterly/annual
 * disclosure filings — the PSE's own filing system) into the
 * `financial_snapshots` table.
 *
 * Honesty contract (mirrors the backfill-pse-history.ts philosophy):
 *  - period_end: parsed from the filing's asOfPeriod (e.g. "Mar 31, 2026").
 *  - snapshot_date: the filing's *publish* date (the `period` field, e.g.
 *    "May 13, 2026 07:39 AM"), not "today" — a snapshot is dated when the
 *    filing actually appeared, so freshness checks stay honest.
 *  - eps: as-reported EPS from the filing.
 *  - roe / roa: netIncome to totalEquity / totalAssets, in percent.
 *  - debt_to_equity: stored as a decimal ratio (1.32 = 132%), matching what
 *    mapFinancialSnapshot expects (it multiplies by 100).
 *  - operating_margin: operatingIncome to revenue, in percent.
 *  - net_margin: netIncome to revenue, in percent (real — negative for
 *    loss-making filers; never clamped or fabricated).
 *  - revenue_growth / profit_growth / eps_growth: period-over-period computed
 *    ONLY within the same cadence (quarterly `series` -> QoQ, `annualSeries`
 *    -> YoY). Mixing a quarterly figure with an annual one would produce a
 *    misleading ratio, so cadences never contaminate each other, and growth is
 *    NULL when the base period is missing or non-positive.
 *  - market_cap, pe_ratio, dividend_yield, beta, free_float, fcf_yield,
 *    ev_ebitda, roic, current_ratio, gross_margin, pb_ratio, fcf_growth:
 *    always NULL — the scraped disclosures carry none of these (shares
 *    outstanding exists for only 1 of 280 symbols), and fabricating them
 *    would defeat the purpose of this project.
 *
 * Rows are inserted oldest->newest per symbol so SQLite's `rowid DESC`
 * ordering (used by retrieveResultEventEvidence's "latest snapshot" query)
 * resolves to the newest period.
 *
 * Usage:
 *   npx tsx scripts/load-pse-financials.ts --dry-run            # sample, no writes
 *   npx tsx scripts/load-pse-financials.ts --limit=5            # 5 symbols, dry-run
 *   npx tsx scripts/load-pse-financials.ts --symbols=SMPH,BDO   # specific, dry-run
 *   npx tsx scripts/load-pse-financials.ts --apply              # write to the DB
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { dbAdapter } from '../src/db/index.js';

const FINANCIAL_HISTORY_PATH = resolve(process.cwd(), 'data/pse-financial-history.json');

const MONTHS: Record<string, number> = {
  jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6,
  jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12,
};

export interface PsePeriod {
  period?: string | null; // filing publish datetime, e.g. "May 13, 2026 07:39 AM"
  asOfPeriod?: string | null; // e.g. "Mar 31, 2026"
  revenue?: number | null;
  netIncome?: number | null;
  totalAssets?: number | null;
  totalEquity?: number | null;
  totalLiabilities?: number | null;
  eps?: number | null;
  operatingIncome?: number | null;
  roe?: number | null; // present only on `latest`
  debtToEquity?: number | null; // present only on `latest`
  sharesOutstanding?: number | null; // present only on `latest`
  scrapedAt?: string | null; // present only on `latest`
}

export interface PseRecord {
  symbol: string;
  latest?: PsePeriod;
  series?: PsePeriod[];
  annualSeries?: PsePeriod[];
  error?: string;
}

export interface SnapshotRow {
  symbol: string;
  period_end: string; // ISO YYYY-MM-DD
  snapshot_date: string; // ISO YYYY-MM-DD (filing publish date)
  market_cap: null;
  pe_ratio: null;
  eps: number | null;
  dividend_yield: null;
  beta: null;
  free_float: null;
  fcf_yield: null;
  ev_ebitda: null;
  roa: number | null;
  roe: number | null;
  roic: null;
  debt_to_equity: number | null;
  current_ratio: null;
  revenue_growth: number | null;
  profit_growth: number | null;
  eps_growth: number | null;
  fcf_growth: null;
  gross_margin: null;
  operating_margin: number | null;
  net_margin: number | null;
  pb_ratio: null;
}

/**
 * "Mar 31, 2026" / "April 30, 2025" / "Aug 14, 2024 10:17 AM" -> "2026-03-31".
 * Handles both abbreviated and full month names (DELM's filings use "April").
 */
export function parseAsOfDate(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const m = /^([A-Za-z]{3,9})\s+(\d{1,2}),\s+(\d{4})/.exec(raw.trim());
  if (!m) return null;
  const month = MONTHS[m[1].slice(0, 3).toLowerCase()];
  if (!month) return null;
  const dd = String(Number(m[2])).padStart(2, '0');
  const mm = String(month).padStart(2, '0');
  return `${m[3]}-${mm}-${dd}`;
}

/** Convenience: the `period` field starts with a date we can reuse. */
export function parseFilingDate(period: string | null | undefined): string | null {
  return parseAsOfDate(period);
}

/** Percent of numer/denom, null when missing/non-positive. */
export function pct(numer: number | null | undefined, denom: number | null | undefined): number | null {
  if (numer === null || numer === undefined || denom === null || denom === undefined) return null;
  if (denom <= 0) return null;
  return Number(((numer / denom) * 100).toFixed(2));
}

/** Decimal ratio, null when missing/non-positive. */
export function ratioOf(numer: number | null | undefined, denom: number | null | undefined): number | null {
  if (numer === null || numer === undefined || denom === null || denom === undefined) return null;
  if (denom <= 0) return null;
  return Number((numer / denom).toFixed(4));
}

/** % change vs a base period; NULL when the base is missing or non-positive. */
export function growthPct(cur: number | null | undefined, prev: number | null | undefined): number | null {
  if (cur === null || cur === undefined || prev === null || prev === undefined) return null;
  if (prev <= 0) return null;
  return Number((((cur - prev) / prev) * 100).toFixed(2));
}

function finiteOrNull(v: number | null | undefined): number | null {
  if (v === null || v === undefined) return null;
  return Number.isFinite(v) ? v : null;
}

function todayIso(): string {
  return new Date().toISOString().slice(0, 10);
}

/** Build the ordered snapshot rows for one symbol from its scraped record. */
export function buildSymbolSnapshots(symbol: string, rec: PseRecord): SnapshotRow[] {
  if (!rec || rec.error) return [];

  const scrapedDate =
    rec.latest?.scrapedAt && /^\d{4}-\d{2}-\d{2}/.test(rec.latest.scrapedAt)
      ? rec.latest.scrapedAt.slice(0, 10)
      : null;

  interface Draft {
    p: PsePeriod;
    cadence: 'series' | 'annualSeries';
    asOf: string;
    snapshotDate: string;
    revGrowth: number | null;
    profitGrowth: number | null;
    epsGrowth: number | null;
  }
  const drafts: Draft[] = [];
  const seen = new Set<string>();

  const addPeriod = (p: PsePeriod, cadence: 'series' | 'annualSeries') => {
    const asOf = parseAsOfDate(p.asOfPeriod);
    if (!asOf || seen.has(asOf)) return; // dedupe (latest usually duplicates series[last])
    seen.add(asOf);
    drafts.push({
      p,
      cadence,
      asOf,
      snapshotDate: parseFilingDate(p.period) ?? scrapedDate ?? todayIso(),
      revGrowth: null,
      profitGrowth: null,
      epsGrowth: null,
    });
  };

  for (const p of rec.series ?? []) addPeriod(p, 'series');
  for (const p of rec.annualSeries ?? []) addPeriod(p, 'annualSeries');
  if (rec.latest) addPeriod(rec.latest, 'series');
  if (drafts.length === 0) return [];

  // Growth is computed only within a cadence (QoQ for series, YoY for annual).
  const byCadence = new Map<'series' | 'annualSeries', Draft[]>();
  for (const d of drafts) {
    const list = byCadence.get(d.cadence) ?? [];
    list.push(d);
    byCadence.set(d.cadence, list);
  }
  for (const list of byCadence.values()) {
    list.sort((a, b) => (a.asOf < b.asOf ? -1 : 1));
    let prev: PsePeriod | null = null;
    for (const d of list) {
      d.revGrowth = growthPct(d.p.revenue, prev?.revenue ?? null);
      d.profitGrowth = growthPct(d.p.netIncome, prev?.netIncome ?? null);
      d.epsGrowth = growthPct(d.p.eps, prev?.eps ?? null);
      prev = d.p;
    }
  }

  drafts.sort((a, b) => (a.asOf < b.asOf ? -1 : 1)); // oldest->newest for rowid DESC
  return drafts.map((d) => ({
    symbol,
    period_end: d.asOf,
    snapshot_date: d.snapshotDate,
    market_cap: null,
    pe_ratio: null,
    eps: finiteOrNull(d.p.eps),
    dividend_yield: null,
    beta: null,
    free_float: null,
    fcf_yield: null,
    ev_ebitda: null,
    roa: pct(d.p.netIncome, d.p.totalAssets),
    roe: pct(d.p.netIncome, d.p.totalEquity),
    roic: null,
    roce: null, // no EBIT / capital-employed breakdown in PSE EDGE → never fabricated
    debt_to_equity: ratioOf(d.p.totalLiabilities, d.p.totalEquity),
    current_ratio: null,
    revenue_growth: d.revGrowth,
    profit_growth: d.profitGrowth,
    eps_growth: d.epsGrowth,
    fcf_growth: null,
    gross_margin: null,
    operating_margin: pct(d.p.operatingIncome, d.p.revenue),
    net_margin: pct(d.p.netIncome, d.p.revenue),
    pb_ratio: null,
  }));
}


const UPSERT_COLUMNS = [
  'symbol', 'period_end', 'snapshot_date', 'market_cap', 'pe_ratio', 'eps', 'dividend_yield', 'beta', 'free_float',
  'fcf_yield', 'ev_ebitda', 'roa', 'roe', 'roic', 'debt_to_equity', 'current_ratio',
  'revenue_growth', 'profit_growth', 'eps_growth', 'fcf_growth', 'gross_margin', 'operating_margin', 'net_margin', 'pb_ratio',
];

async function upsertRows(rows: SnapshotRow[]): Promise<void> {
  for (const r of rows) {
    const placeholders = UPSERT_COLUMNS.map((_, i) => `$${i + 1}`).join(',');
    await dbAdapter.query(
      `INSERT OR REPLACE INTO financial_snapshots (${UPSERT_COLUMNS.join(',')})
       VALUES (${placeholders})`,
      [
        r.symbol, r.period_end, r.snapshot_date, r.market_cap, r.pe_ratio, r.eps, r.dividend_yield, r.beta, r.free_float,
        r.fcf_yield, r.ev_ebitda, r.roa, r.roe, r.roic, r.debt_to_equity, r.current_ratio,
        r.revenue_growth, r.profit_growth, r.eps_growth, r.fcf_growth, r.gross_margin, r.operating_margin, r.net_margin, r.pb_ratio,
      ],
    );
  }
}

interface Cli {
  apply: boolean;
  limit?: number;
  symbols?: string[];
}

export function parseArgs(argv: string[]): Cli {
  const cli: Cli = { apply: false };
  for (const a of argv) {
    if (a === '--apply') cli.apply = true;
    else if (a === '--dry-run') cli.apply = false;
    else if (a.startsWith('--limit=')) cli.limit = Number(a.split('=')[1]);
    else if (a.startsWith('--symbols=')) {
      cli.symbols = a.split('=')[1].split(',').map((s) => s.trim().toUpperCase()).filter(Boolean);
    }
  }
  return cli;
}

async function main() {
  const cli = parseArgs(process.argv.slice(2));
  await dbAdapter.initialize();
  console.log(`DB adapter: ${dbAdapter.kind} (${cli.apply ? 'APPLY — will write' : 'DRY-RUN — no writes'})`);

  const raw = JSON.parse(readFileSync(FINANCIAL_HISTORY_PATH, 'utf-8'));
  const records = (raw.results ?? raw) as Record<string, PseRecord>;
  const base = (cli.symbols ?? Object.keys(records)).filter((s) => records[s]);
  const targets = cli.limit ? base.slice(0, cli.limit) : base;

  let rowsTotal = 0, symbolsLoaded = 0, symbolsSkipped = 0;
  const coverage = { eps: 0, roe: 0, roa: 0, debtToEquity: 0, opMargin: 0, anyGrowth: 0 };
  const skipped: string[] = [];

  for (const symbol of targets) {
    const rec = records[symbol];
    if (!rec || rec.error) {
      symbolsSkipped++;
      skipped.push(`${symbol} (${rec?.error ?? 'missing record'})`);
      continue;
    }
    const rows = buildSymbolSnapshots(symbol, rec);
    if (rows.length === 0) {
      symbolsSkipped++;
      skipped.push(`${symbol} (no parseable periods)`);
      continue;
    }
    if (cli.apply) await upsertRows(rows);
    symbolsLoaded++;
    rowsTotal += rows.length;
    for (const r of rows) {
      if (r.eps !== null) coverage.eps++;
      if (r.roe !== null) coverage.roe++;
      if (r.roa !== null) coverage.roa++;
      if (r.debt_to_equity !== null) coverage.debtToEquity++;
      if (r.operating_margin !== null) coverage.opMargin++;
      if (r.revenue_growth !== null || r.profit_growth !== null || r.eps_growth !== null) coverage.anyGrowth++;
    }
  }

  console.log(`\nSymbols: ${symbolsLoaded} loaded, ${symbolsSkipped} skipped`);
  if (skipped.length) console.log(`Skipped: ${skipped.join(', ')}`);
  console.log(`Periods: ${rowsTotal} total, ${(rowsTotal / Math.max(symbolsLoaded, 1)).toFixed(1)} per symbol`);
  console.log(`Coverage: eps=${coverage.eps} roe=${coverage.roe} roa=${coverage.roa} debt_to_equity=${coverage.debtToEquity} operating_margin=${coverage.opMargin} any_growth=${coverage.anyGrowth}`);
  console.log('Deliberately NULL (no source data): market_cap, pe_ratio, dividend_yield, beta, free_float, fcf_yield, ev_ebitda, roic, current_ratio, gross_margin, pb_ratio, fcf_growth');

  const smph = buildSymbolSnapshots('SMPH', records['SMPH']);
  const latestSmp = smph[smph.length - 1];
  if (latestSmp) {
    console.log(`\nSample — SMPH newest snapshot (${latestSmp.period_end}, filed ${latestSmp.snapshot_date}):`);
    console.log(JSON.stringify(latestSmp, null, 2));
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

